def reserve(stock, requests):
    totals = {}
    for sku, qty in requests:
        if type(qty) is not int or qty <= 0: raise ValueError('quantity')
        totals[sku] = totals.get(sku, 0) + qty
    if any(s not in stock or stock[s] < q for s,q in totals.items()): return False
    for s,q in totals.items(): stock[s] -= q
    return True

